#!/usr/bin/env node
// Executable entry point: node src/todo-cli.js <command> [args]
import { runTodoCli } from './todo.js'

const { code, stdout, stderr } = await runTodoCli(process.argv.slice(2), { cwd: process.cwd() })
if (stdout) process.stdout.write(`${stdout}\n`)
if (stderr) process.stderr.write(`${stderr}\n`)
process.exitCode = code

